sys_script_include.script:
var NotificationLogService = Class.create();

NotificationLogService.prototype = {

    initialize: function() {
        this.validationUtils = new ValidationUtils();
    },

    /**
     * Check whether a Notification Log record exists.
     *
     * @param {String} notificationSysId
     * @return {Boolean}
     */
    notificationExists: function(notificationSysId) {

        if (this.validationUtils.isEmpty(notificationSysId)) {
            return false;
        }

        var notification = new GlideRecord(
            'x_2130921_caresy_0_notification_log'
        );

        if (!notification.isValid()) {
            gs.error(
                'NotificationLogService: Notification Log table is invalid.'
            );
            return false;
        }

        return notification.get(notificationSysId);
    },

    /**
     * Retrieve a Notification Log record.
     *
     * @param {String} notificationSysId
     * @return {GlideRecord|null}
     */
    getNotification: function(notificationSysId) {

        if (this.validationUtils.isEmpty(notificationSysId)) {
            return null;
        }

        var notification = new GlideRecord(
            'x_2130921_caresy_0_notification_log'
        );

        if (!notification.isValid()) {
            gs.error(
                'NotificationLogService: Notification Log table is invalid.'
            );
            return null;
        }

        if (notification.get(notificationSysId)) {
            return notification;
        }

        return null;
    },

    /**
     * Check whether a Notification Log record is active.
     *
     * @param {String} notificationSysId
     * @return {Boolean}
     */
    isNotificationActive: function(notificationSysId) {

        var notification = this.getNotification(notificationSysId);

        if (!notification) {
            return false;
        }

        return notification.getValue('active') == '1';
    },

    type: 'NotificationLogService'
};
